import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { parseCsv, validateTargetIdentityReconciliation } from './verify-target-identity-reconciliation.mjs';
const fixture=JSON.parse(fs.readFileSync('docs/data/target-identity-reconciliation.json','utf8'));
const tkb=JSON.parse(fs.readFileSync('docs/data/target-knowledge-base.json','utf8'));
const rows=parseCsv(fs.readFileSync('data/analytics/metadata/session-scientific-metadata.csv','utf8'));
const clone=x=>structuredClone(x);
const rejects=(mutate,pattern,mutateRows)=>{const x=clone(fixture), r=clone(rows); mutate(x); if(mutateRows) mutateRows(r); assert.match(validateTargetIdentityReconciliation(x,tkb,r).join('\n'),pattern);};
test('accepted bounded F3 reconciliation validates',()=>assert.deepEqual(validateTargetIdentityReconciliation(fixture,tkb,rows),[]));
test('rejects authority escalation',()=>rejects(x=>x.authority='authoritative',/authority must remain projection/));
test('rejects source authority promotion',()=>rejects(x=>x.source_contract.authority='scientific_authority',/bounded analytics projection/));
test('rejects PARTIAL metadata as accepted source',()=>rejects(x=>x.matches[1].session_ids=['2026-08-10_2026-08-11'],/missing\/non-REGISTERED/));
test('rejects target id disagreement across evidence',()=>rejects(()=>{},/target_id disagreement/,r=>{r.find(x=>x.session_id==='2026-07-15_2026-07-16').target_id='TGT-OTHER';}));
test('rejects canonical name disagreement across evidence',()=>rejects(()=>{},/target_name disagreement/,r=>{r.find(x=>x.session_id==='2026-08-15_2026-08-16').target_name='M27';}));
test('rejects arbitrary alias without governed evidence',()=>rejects(x=>x.matches[1].aliases=['Dumbbell Nebula'],/aliases require explicit governed alias evidence/));
test('rejects source ref misbinding',()=>rejects(x=>x.matches[0].source_refs[0]='analytics-metadata:wrong',/source_refs must bind exactly/));
test('rejects identifier reused by another target key',()=>rejects(x=>x.matches[1].target_id=x.matches[0].target_id,/maps to multiple target keys/));
test('rejects F2 canonical identity mutation',()=>rejects(x=>x.matches[0].canonical_name='LDN1320',/canonical name must preserve F2 identity/));
test('rejects match bound expansion',()=>rejects(x=>x.matches=[...x.matches,...x.matches,...x.matches],/match bound exceeded/));
